previewCss:
.darma-loader-darma-b15-bubble-sort-bars { --accent: var(--loader-color, #4338ca); --accent-2: var(--loader-secondary-color, #facc15); width: var(--loader-size, 124px); height: calc(var(--loader-size, 124px) * .6); position: relative; }
.darma-loader-darma-b15-bubble-sort-bars span { position: absolute; bottom: 0; width: 12%; border-radius: 3px 3px 0 0; background: linear-gradient(color-mix(in srgb, #fff 20%, var(--accent)), var(--accent)); }
.darma-loader-darma-b15-bubble-sort-bars span:nth-of-type(1) { left: 1%; height: 40%; }
.darma-loader-darma-b15-bubble-sort-bars span:nth-of-type(2) { left: 18%; height: 62%; }
.darma-loader-darma-b15-bubble-sort-bars span:nth-of-type(3) { left: 35%; height: 28%; animation: darma-loader-darma-b15-bubble-sort-bars-sortbar-swap-up calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b15-bubble-sort-bars span:nth-of-type(4) { left: 52%; height: 84%; animation: darma-loader-darma-b15-bubble-sort-bars-sortbar-swap-down calc(var(--loader-speed, 1s) * 2.6) ease-in-out infinite; }
.darma-loader-darma-b15-bubble-sort-bars span:nth-of-type(5) { left: 69%; height: 52%; }
.darma-loader-darma-b15-bubble-sort-bars span:nth-of-type(6) { left: 86%; height: 96%; }
.darma-loader-darma-b15-bubble-sort-bars .darma-loader-darma-b15-bubble-sort-bars__scan { position: absolute; bottom: 0; left: 0; width: 29%; height: 100%; border-radius: 5px; background: color-mix(in srgb, var(--accent-2) 32%, transparent); box-shadow: inset 0 0 0 2px var(--accent-2); animation: darma-loader-darma-b15-bubble-sort-bars-sortbar-scan calc(var(--loader-speed, 1s) * 2.6) steps(4, end) infinite; }
@keyframes darma-loader-darma-b15-bubble-sort-bars-sortbar-scan { 0% { transform: translateX(0); } 100% { transform: translateX(240%); } }
@keyframes darma-loader-darma-b15-bubble-sort-bars-sortbar-swap-up { 0%, 42% { transform: translateX(0) translateY(0); } 54% { transform: translateX(0) translateY(-40%); } 66% { transform: translateX(142%) translateY(-40%); } 78%, 100% { transform: translateX(142%) translateY(0); } }
@keyframes darma-loader-darma-b15-bubble-sort-bars-sortbar-swap-down { 0%, 42% { transform: translateX(0) translateY(0); } 54% { transform: translateX(0) translateY(-8%); } 66% { transform: translateX(-142%) translateY(-8%); } 78%, 100% { transform: translateX(-142%) translateY(0); } }

